import{a as e,c as t,i as n,l as r,o as i,r as a,s as o,t as s,u as c}from"./app-C4mzCnKe.js";var l=JSON.parse(`{"path":"/evaluator.html","title":"评估器设计（过程评估）","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"evaluator.md"}`),u={name:`evaluator.md`};function d(s,l,u,d,f,p){let m=r(`RouteLink`),h=r(`Mermaid`);return t(),n(`div`,null,[l[26]||=e(`<h1 id="评估器设计-过程评估" tabindex="-1"><a class="header-anchor" href="#评估器设计-过程评估"><span>评估器设计（过程评估）</span></a></h1><blockquote><p><strong>初稿</strong> · 评估器是「过程进化」的评判引擎，由<strong>会话评估官</strong>持有。本页定它「在系统中的位置」与「功能」，会话业务相关的评估器清单是初版，后面随具体业务持续打磨。</p></blockquote><h2 id="一、评估器在系统中的位置" tabindex="-1"><a class="header-anchor" href="#一、评估器在系统中的位置"><span>一、评估器在系统中的位置</span></a></h2><p>评估器不是独立 Agent，而是<strong>会话评估官</strong>手里的机制——用来判断「推理质量 / 工具效率 / 协议合规 / 成本」这些<strong>开放语义</strong>好不好。</p><p>它在系统里卡在三个交接点上：</p><table><thead><tr><th>交接点</th><th>上游（喂什么）</th><th>下游（出什么）</th></tr></thead><tbody><tr><td>可观测 → 评估</td><td>会话评估官读 trace（四元 id + 三层语义）</td><td>评估结论：badcase 定位 + 置信度</td></tr><tr><td>评估 → 进化</td><td>评估结论（badcase 率按节点统计）</td><td>过程归因 → 改 prompt/skill/协议</td></tr><tr><td>评估 → 门禁</td><td>评估结果 + 证据</td><td>三重门控（增益/遗忘/安全）→ 发布/回滚</td></tr></tbody></table>`,6),a(`p`,null,[l[1]||=a(`strong`,null,`与「信用传播」的分水岭`,-1),l[2]||=i(`：结果归因（因子/策略，可验证）用信用传播；过程评估（开放语义）用评估器。分水岭的完整解释见 `,-1),o(m,{to:`/eval-platform.html`},{default:c(()=>[...l[0]||=[i(`评测与可观测`,-1)]]),_:1}),l[3]||=i(`。`,-1)]),l[27]||=e(`<h2 id="二、评估器是什么-三要素" tabindex="-1"><a class="header-anchor" href="#二、评估器是什么-三要素"><span>二、评估器是什么：三要素</span></a></h2><p>一个评估器 = 给「某类过程问题」定义一套<strong>可复核的判断标准</strong>：</p><table><thead><tr><th>要素</th><th>含义</th><th>为什么只给这么多</th></tr></thead><tbody><tr><td><strong>证据</strong></td><td>只取必要 span（某次推理的输入/输出、某次工具调用的入参/返回），不看整条 trace</td><td>准确（减少无关材料干扰）、省钱（token 更少）、更快</td></tr><tr><td><strong>边界</strong></td><td>什么算 bad、什么算 good、什么算「待复核」</td><td>边界不清 = 评估器自己来回翻</td></tr><tr><td><strong>判定</strong></td><td>粗筛规则（0 LLM）+ LLM Judge 精判（Pro/GLM）</td><td>能规则的用规则，不能的才上 LLM</td></tr></tbody></table><blockquote><p><strong>判定方法也遵循「能规则就用规则」</strong>：协议合规、成本预算这类可机器验证的，用规则断言；推理质量、工具效率这类开放语义，才用 LLM Judge。这是「因子用公式、过程用评估器」的分水岭在<strong>评估器内部更细一层</strong>上的同样应用。</p></blockquote><h2 id="三、评估粒度-结果-节点-轨迹" tabindex="-1"><a class="header-anchor" href="#三、评估粒度-结果-节点-轨迹"><span>三、评估粒度：结果 / 节点 / 轨迹</span></a></h2><p>评估目标决定取数范围，会话过程可在三层粒度上评估，多轮可跨层核对：</p><table><thead><tr><th>粒度</th><th>看什么</th><th>能检查什么</th></tr></thead><tbody><tr><td><strong>结果</strong></td><td>最终回答 / 决策包</td><td>是否完成目标、结论是否有依据</td></tr><tr><td><strong>节点</strong></td><td>指定 span 的入参与返回值（某次工具调用、某次模型调用）</td><td>查询参数对不对、工具返回对不对、节点是否满足约束</td></tr><tr><td><strong>轨迹</strong></td><td>相关 span 与步骤关系</td><td>必查项覆盖、步骤关系、过程约束是否保留</td></tr></tbody></table><blockquote><p>局部通过 ≠ 任务完成；证据不足需复核，不默认通过。</p></blockquote><h2 id="四、股票场景的评估器清单-初稿" tabindex="-1"><a class="header-anchor" href="#四、股票场景的评估器清单-初稿"><span>四、股票场景的评估器清单（初稿）</span></a></h2><p>会话评估官针对<strong>四类过程问题</strong>各定义一个评估器。此清单是初版，随具体会话业务打磨。</p><h3 id="_4-1-推理质量评估器" tabindex="-1"><a class="header-anchor" href="#_4-1-推理质量评估器"><span>4.1 推理质量评估器</span></a></h3><ul><li><strong>证据</strong>：主控意图理解 span（用户意图 → 规划）+ 策略师推理 span（假设 → 结论）</li><li><strong>边界</strong>：bad = 遗漏任务约束、答非所问、张冠李戴（把 A 股当 B 股、把「近 3 日」当「昨日」）；good = 完整覆盖约束、结论有依据</li><li><strong>判定</strong>：LLM Judge（Pro），低置信升级复核</li><li><strong>示例</strong>：主控理解「诊断账户近 3 日表现」，策略师却只查「昨日」→ bad</li></ul><h3 id="_4-2-工具效率评估器" tabindex="-1"><a class="header-anchor" href="#_4-2-工具效率评估器"><span>4.2 工具效率评估器</span></a></h3><ul><li><strong>证据</strong>：工具调用 span（入参 / 返回）+ 数据取数 span（口径字段）</li><li><strong>边界</strong>：bad = 重复调用、用错工具、遗漏必要取数、口径错配；good = 调用符合契约、取数完整</li><li><strong>判定</strong>：规则粗筛（0 LLM）+ LLM Judge 精判</li><li><strong>示例</strong>：数据管家取「涨停家数」却用了错误的板块口径 → bad</li></ul><h3 id="_4-3-协议合规评估器" tabindex="-1"><a class="header-anchor" href="#_4-3-协议合规评估器"><span>4.3 协议合规评估器</span></a></h3><ul><li><strong>证据</strong>：消息信封 span（四元 id / 类型 / schema 版本 / 幂等键）+ 写域操作</li><li><strong>边界</strong>：bad = 越权写生产、消息格式不合规、缺幂等键；good = 协议执行正确</li><li><strong>判定</strong>：规则（机械断言，0 LLM，协议总线进总线即校验）</li><li><strong>示例</strong>：主控越权写判决库 → bad（ACL 拦截，进不了判决器）</li></ul><h3 id="_4-4-成本预算评估器" tabindex="-1"><a class="header-anchor" href="#_4-4-成本预算评估器"><span>4.4 成本预算评估器</span></a></h3><ul><li><strong>证据</strong>：token / 时延 / 调用量 span</li><li><strong>边界</strong>：bad = 超出预算（P95 时延超上限、单次成本超预算）；good = 在预算内</li><li><strong>判定</strong>：规则（0 LLM）</li><li><strong>示例</strong>：一次复盘 Pro 调用超预算 → bad</li></ul><h2 id="五、多阶段降本-粗筛规则-llm-judge-精判" tabindex="-1"><a class="header-anchor" href="#五、多阶段降本-粗筛规则-llm-judge-精判"><span>五、多阶段降本：粗筛规则 + LLM Judge 精判</span></a></h2><p>过程评估不必每条都喂 Pro——先粗筛，只有「异常」才精判：</p>`,20),o(h,{code:``}),l[28]||=e(`<table><thead><tr><th>阶段</th><th>手段</th><th>成本</th><th>处理量</th></tr></thead><tbody><tr><td>粗筛</td><td>协议合规、成本预算、口径校验（规则）</td><td>0 LLM</td><td>全量</td></tr><tr><td>精判</td><td>推理质量、工具效率（LLM Judge）</td><td>少量</td><td>仅粗筛通过 + 需要语义判断的</td></tr></tbody></table>`,1),a(`blockquote`,null,[a(`p`,null,[l[5]||=i(`这是「多阶段降本」的`,-1),l[6]||=a(`strong`,null,`过程侧`,-1),l[7]||=i(`；`,-1),l[8]||=a(`strong`,null,`结果侧`,-1),l[9]||=i(`（规则 → 统计 → LLM 复盘）见 `,-1),o(m,{to:`/observability.html`},{default:c(()=>[...l[4]||=[i(`可观测平台设计`,-1)]]),_:1}),l[10]||=i(` 的多阶段评估。`,-1)])]),l[29]||=e(`<h2 id="六、评估器开发流程-skill-cli" tabindex="-1"><a class="header-anchor" href="#六、评估器开发流程-skill-cli"><span>六、评估器开发流程（Skill + CLI）</span></a></h2><p>一个评估器从定义到上线，走五步闭环，正确率不达标不上线：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">① 定义评估器（证据 / 边界 / 判定步骤）</span>
<span class="line">→ ② 准备数据集（标注好的 good/bad 样本）</span>
<span class="line">→ ③ 批量评测（在数据集上跑，算 badcase 正确率）</span>
<span class="line">→ 达到上线门槛？</span>
<span class="line">   是 → ⑤ 上线（接入流水线，进 badcase 看板）</span>
<span class="line">   否 → ④ 错例分析与修正（调边界 / 证据 / 判定步骤）→ 回到 ③</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>评估器开发 Skill</strong>：把「定义 / 评测 / 错例修正」的方法沉淀下来，交给会话评估官执行。</li><li><strong>配套 CLI</strong>：命令行完成数据集评测 / 错例查看 / 上线发布，便于反复迭代。</li></ul><h2 id="七、有效性验证三件套" tabindex="-1"><a class="header-anchor" href="#七、有效性验证三件套"><span>七、有效性验证三件套</span></a></h2><p>评估器上线前必须过三关，否则「改 prompt」没有可靠依据：</p><ol><li><strong>对照人工标注</strong>：正例 / 反例 / 边界样本，按同一标准逐条比对。</li><li><strong>看误判漏判</strong>：符合要求却判失败 = 误判；不满足却判通过 = 漏判。</li><li><strong>预留样本验证</strong>：校准后验证未参与调整的样本。</li></ol><h2 id="八、数据集建设-三集分离" tabindex="-1"><a class="header-anchor" href="#八、数据集建设-三集分离"><span>八、数据集建设：三集分离</span></a></h2>`,8),a(`p`,null,[l[12]||=i(`过程评测集的样本资产（基准集/回归集/校准集 + 单 case 结构 / 分布 / 构建 / GT / 隔离 / 问题集）见 `,-1),o(m,{to:`/eval-dataset.html`},{default:c(()=>[...l[11]||=[i(`评测集设计`,-1)]]),_:1}),l[13]||=i(`。这里只强调一句：`,-1),l[14]||=a(`strong`,null,`回归集不替代基准集，校准用独立样本`,-1),l[15]||=i(`。`,-1)]),l[30]||=a(`h2`,{id:`九、质量准出-三重门控`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#九、质量准出-三重门控`},[a(`span`,null,`九、质量准出：三重门控`)])],-1),a(`p`,null,[l[17]||=i(`过程进化的「发布门禁」（增益/遗忘/安全）权威版在 `,-1),o(m,{to:`/self-evolution.html`},{default:c(()=>[...l[16]||=[i(`自进化设计`,-1)]]),_:1}),l[18]||=i(` 第 5 节。评估器只负责产出「可复核的 badcase 判定」，门禁的发布/回滚由进化层执行——评估器不越权做发布决策。`,-1)]),l[31]||=a(`h2`,{id:`十、指标驱动归因-在线复核-双轨闭环-过程版`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#十、指标驱动归因-在线复核-双轨闭环-过程版`},[a(`span`,null,`十、指标驱动归因 + 在线复核 + 双轨闭环（过程版）`)])],-1),l[32]||=a(`ul`,null,[a(`li`,null,[a(`strong`,null,`指标驱动归因`),i(`：过程 badcase 率按节点（意图/规划/工具/检索/回答）统计 → 定位「哪个环节推理质量差 / 哪个工具效率低」。`)]),a(`li`,null,[a(`strong`,null,`在线复核`),i(`：筛选复核样本（低置信 + 异常），人工核对评分与证据，区分「Agent 问题 / 评估器误判 / 数据配置问题 / 证据不足」。`)]),a(`li`,null,[a(`strong`,null,`双轨闭环`),i(`：在线发现问题 → 人工复核标注 → 补入回归/校准集；离线用回归/校准集验证 prompt/skill 修改 → 门禁 → 发布。`)])],-1),a(`blockquote`,null,[a(`p`,null,[l[20]||=i(`这是「指标归因」的`,-1),l[21]||=a(`strong`,null,`过程侧`,-1),l[22]||=i(`；`,-1),l[23]||=a(`strong`,null,`结果侧`,-1),l[24]||=i(`（因子失效/出场太慢等）见 `,-1),o(m,{to:`/observability.html`},{default:c(()=>[...l[19]||=[i(`可观测平台设计`,-1)]]),_:1}),l[25]||=i(` 第 5 节。`,-1)])]),l[33]||=e(`<h2 id="初稿待打磨项" tabindex="-1"><a class="header-anchor" href="#初稿待打磨项"><span>初稿待打磨项</span></a></h2><ul><li>[ ] 四类评估器的<strong>边界</strong>要随真实会话业务补正例/反例（尤其推理质量的「遗漏约束」边界最难定）。</li><li>[ ] 评估器清单按业务扩展到「记忆遗漏、指令泄露、自我认知」等（对应 AI NEX 的典型问题表，但落到股票场景）。</li><li>[ ] 数据集三集的<strong>样本量 / 标注口径</strong>要在真实会话流量上定。</li><li>[ ] 「有效性验证三件套」的<strong>正确率达标线</strong>（多少算达标）待定。</li><li>[ ] 在线复核的<strong>抽样比例</strong>与「Agent 问题 vs 评估器误判」的仲裁流程待细化。</li></ul>`,2)])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};